/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The <t>PurchTable</t> table extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderLineV2Entity))]
final class METPurchPurchaseOrderLineV2Entity_Extension
{
}

Method.Source:
    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        MetItemSiteSettingsSetup    metItemSiteSettingsSetup;
        PurchTotals                 purchTotals;
        TaxPurch                    taxPurch;

        select firstonly TempRcvLimit 
            from metItemSiteSettingsSetup 
            where metItemSiteSettingsSetup.ItemId == this.ItemNumber 
            && metItemSiteSettingsSetup.InventSiteId == this.ReceivingSiteId;

        this.METPOLineTempRcvLimit = metItemSiteSettingsSetup.TempRcvLimit ? metItemSiteSettingsSetup.TempRcvLimit: InventTable::find(this.ItemNumber).PdsBestBefore;

        this.METPOLineInventoryUOM = InventTableModule::find(this.ItemNumber,ModuleInventPurchSales::Invent).UnitId;
        
        purchTotals = PurchTotals::newPurchTable(PurchTable::find(this.PurchaseOrderNumber));
        purchTotals.calc();
        taxPurch = purchTotals.tax();

        this.METPOlineTaxAmount = conPeek(taxPurch.showTaxesSourceSingleLine(tableNum(PurchLine), PurchLine::findInventTransId(this.InventoryLotId).RecId), 2);

        next postload();
    }

    /// <summary>
    /// getPOLineConfPurchGTIN method COC
    /// </summary>
    /// <returns> string value</returns>
    private static server str getPOLineConfPurchGTIN()
    {
        str                 metBarcode;
        SysDictTable        metDictInventItemBarcode = new SysDictTable(tableNum(InventItemBarcode));
        str                 metItemId;
        str                 metUom;
        str                 metSqlQuery = 'SELECT TOP 1 %1 FROM %2 WHERE %2.%3 = %4 AND %2.%5 = %6';
              

        metItemId = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderLineV2Entity), dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, PurchLine),
                        fieldStr(PurchLine, itemid));
        
        metUom = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderLineV2Entity), dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, PurchLine),
                        fieldStr(PurchLine,purchunit));
        
        metBarcode = strFmt(@metSqlQuery,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemBarCode), DbBackend::Sql),
                            metDictInventItemBarcode.name(DbBackend::Sql),
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, ItemId), DbBackend::Sql),
                            metItemId,
                            metDictInventItemBarcode.fieldName(fieldNum(InventItemBarcode, UnitId), DbBackend::Sql),
                            metUom);

        return metBarcode;
    }

/// <summary>
/// CoC method for InsertEntityDataSource method
/// </summary>
/// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
/// <returns>true of false</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);;
 
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, METPurchLine))
    {
        _entityCtx.detectConflictForDatasource(_dataSourceCtx);
    }

    return ret;
}

    /// <summary>
    /// Finds record buffer for data source and return
    /// </summary>
    /// <param name = "_entityCtx">Entity context</param>
    /// <param name = "_dataSourceCtx">Data source runtime context</param>
    /// <returns>Record buffer associated with data source</returns>
    public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        Common ret = next findEntityDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(PurchPurchaseOrderLineV2Entity, METPurchLine))
        {
            ret = METPurchLine::find(this.METPurchLineRecid);
        }

        return ret;
    }
